<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { ArrowLeft, Delete, Download, Refresh, Star, UploadFilled, VideoPlay } from '@element-plus/icons-vue'
import { api, getCSRFToken, jsonBody } from '../lib/api'

interface Binding{storageId:string;rootPath:string}
interface Album{id:string;name:string;description:string;coverMediaId?:string;backupMode:string;backupEnabled:boolean;scanStatus:string;scanError:string;tags:string[];mediaCount:number;primary:Binding;backup?:Binding}
interface Media{id:string;albumId:string;relativePath:string;kind:'image'|'video';mimeType:string;size:number;modifiedAt:string;sourceVersion:string;processingStatus:string}
interface UploadState{name:string;progress:number;status:string}
const route=useRoute();const router=useRouter();const album=ref<Album>();const items=ref<Media[]>([]);const nextCursor=ref('');const loading=ref(false);const selected=ref(new Set<string>());const preview=ref<Media>();const uploads=ref<UploadState[]>([]);const broken=ref(new Set<string>())
const selectedItems=computed(()=>items.value.filter(i=>selected.value.has(i.id)))
async function load(reset=true){loading.value=true;try{album.value=await api<Album>(`/albums/${route.params.id}`);const result=await api<{items:Media[]|null;nextCursor:string}>(`/albums/${route.params.id}/media?limit=80${!reset&&nextCursor.value?`&cursor=${encodeURIComponent(nextCursor.value)}`:''}`);const page=result.items||[];items.value=reset?page:[...items.value,...page];nextCursor.value=result.nextCursor}catch(error){ElMessage.error((error as Error).message)}finally{loading.value=false}}
async function scan(){try{await api(`/albums/${route.params.id}/scan`,{method:'POST'});ElMessage.success('扫描任务已加入队列');setTimeout(()=>load(),1200)}catch(error){ElMessage.error((error as Error).message)}}
function toggle(id:string){const next=new Set(selected.value);next.has(id)?next.delete(id):next.add(id);selected.value=next}
async function setCover(){const item=selectedItems.value[0];if(!item||item.kind!=='image')return ElMessage.warning('请选择一张图片');try{await api(`/albums/${route.params.id}/cover`,{method:'PUT',body:jsonBody({mediaId:item.id})});ElMessage.success('封面已更新');await load()}catch(error){ElMessage.error((error as Error).message)}}
async function download(){try{const result=await api<{url:string}>('/download-tickets',{method:'POST',body:jsonBody({albumId:String(route.params.id),mediaIds:Array.from(selected.value)})});window.location.assign(result.url)}catch(error){ElMessage.error((error as Error).message)}}
async function remove(){try{await ElMessageBox.confirm('只会把相册移出 ialbum，不会删除任何存储中的媒体。','移出相册',{confirmButtonText:'确认移出',cancelButtonText:'取消',type:'warning'});await api(`/albums/${route.params.id}`,{method:'DELETE'});await router.push('/albums')}catch(error){if(error!=='cancel')ElMessage.error((error as Error).message)}}
async function onFiles(event:Event){const input=event.target as HTMLInputElement;const files=Array.from(input.files||[]);input.value='';await enqueueFiles(files)}
function preventWindowDrop(event:DragEvent){event.preventDefault()}
function onWindowDrop(event:DragEvent){event.preventDefault();void enqueueFiles(Array.from(event.dataTransfer?.files||[]))}
async function enqueueFiles(files:File[]){if(!files.length)return;const states=files.map(file=>({name:file.name,progress:0,status:'等待中'}));uploads.value.push(...states);let index=0;async function worker(){while(index<files.length){const current=index++;const state=states[current];state.status='上传中';try{await uploadXHR(files[current],state);state.status='已完成';state.progress=100}catch(error){state.status=(error as Error).message}}};await Promise.all([worker(),worker()]);await load();setTimeout(()=>{uploads.value=uploads.value.filter(u=>!states.includes(u))},2500)}
function uploadXHR(file:File,state:UploadState){return new Promise<void>((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST',`/api/v1/albums/${route.params.id}/media`);xhr.setRequestHeader('X-CSRF-Token',getCSRFToken());xhr.setRequestHeader('Idempotency-Key',crypto.randomUUID());xhr.upload.onprogress=e=>{if(e.lengthComputable)state.progress=Math.round(e.loaded/e.total*100)};xhr.onload=()=>xhr.status>=200&&xhr.status<300?resolve():reject(new Error(JSON.parse(xhr.responseText||'{}').error?.message||'上传失败'));xhr.onerror=()=>reject(new Error('网络连接中断'));const data=new FormData();data.append('file',file);xhr.send(data)})}
function mediaURL(item:Media){return `/api/v1/media/${item.id}/content`}
function thumbURL(item:Media){return `/api/v1/media/${item.id}/thumbnails/grid?v=${item.sourceVersion}`}
function prettySize(size:number){if(size<1024*1024)return`${(size/1024).toFixed(0)} KB`;if(size<1024**3)return`${(size/1024**2).toFixed(1)} MB`;return`${(size/1024**3).toFixed(1)} GB`}
onMounted(()=>{void load();window.addEventListener('dragover',preventWindowDrop);window.addEventListener('drop',onWindowDrop)})
onBeforeUnmount(()=>{window.removeEventListener('dragover',preventWindowDrop);window.removeEventListener('drop',onWindowDrop)})
</script>
<template><section class="page"><header class="page-heading"><div><router-link to="/albums" class="muted" style="display:inline-flex;align-items:center;gap:5px;margin-bottom:16px"><el-icon><ArrowLeft/></el-icon>全部相册</router-link><h1>{{ album?.name || '相册' }}</h1><p class="subtitle">{{ album?.description || `${album?.mediaCount||0} 项媒体 · ${album?.backup?'已配置备份':'仅主存储'}` }}</p><div v-if="album?.tags?.length" class="tag-row"><span v-for="tag in album.tags" :key="tag">{{tag}}</span></div></div><div style="display:flex;gap:10px;flex-wrap:wrap"><el-button :icon="Refresh" @click="scan">重新扫描</el-button><label class="el-button el-button--primary"><el-icon style="margin-right:6px"><UploadFilled/></el-icon>上传媒体<input type="file" multiple accept="image/jpeg,image/png,image/webp,image/gif,video/mp4,video/quicktime,video/webm,.mkv,.avi" hidden @change="onFiles"></label><el-dropdown><el-button>更多</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item :icon="Delete" @click="remove">移出 ialbum</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></header><el-alert v-if="album?.scanError" type="error" :closable="false" :title="album.scanError" style="margin-bottom:20px"/><div v-if="uploads.length" class="surface" style="padding:16px 18px;margin-bottom:22px"><div v-for="item in uploads" :key="item.name" style="display:grid;grid-template-columns:1fr 160px 90px;gap:12px;align-items:center;margin:7px 0"><span style="overflow:hidden;text-overflow:ellipsis">{{item.name}}</span><el-progress :percentage="item.progress" :stroke-width="7"/><span class="muted" style="font-size:12px">{{item.status}}</span></div></div><div v-if="selected.size" class="toolbar surface" style="padding:12px 15px;position:sticky;top:12px;z-index:10"><strong>已选择 {{selected.size}} 项</strong><el-button :icon="Download" @click="download">下载所选</el-button><el-button v-if="selectedItems.length===1&&selectedItems[0].kind==='image'" :icon="Star" @click="setCover">设为封面</el-button><el-button text @click="selected=new Set()">取消选择</el-button></div><div v-loading="loading"><div v-if="items.length" class="media-grid"><article v-for="item in items" :key="item.id" class="media-card" @dblclick="preview=item"><el-checkbox class="media-check" :model-value="selected.has(item.id)" @change="toggle(item.id)" @click.stop/><img v-if="!broken.has(item.id)" :src="thumbURL(item)" :alt="item.relativePath" loading="lazy" @error="broken.add(item.id)"><div v-else class="media-placeholder"><el-icon><VideoPlay v-if="item.kind==='video'"/><span v-else>i</span></el-icon></div><span v-if="item.kind==='video'" class="video-badge">VIDEO</span><div class="media-overlay">{{item.relativePath}} · {{prettySize(item.size)}}</div></article></div><div v-else class="surface empty-state"><div class="empty-icon"><el-icon><UploadFilled/></el-icon></div><h2>这个目录还没有媒体</h2><p>拖入照片或视频，或把文件直接放进主存储目录后重新扫描。</p></div><div v-if="nextCursor" style="text-align:center;margin-top:25px"><el-button :loading="loading" @click="load(false)">加载更多</el-button></div></div><el-dialog v-model="preview" width="min(1040px,94vw)" destroy-on-close :title="preview?.relativePath"><img v-if="preview?.kind==='image'" :src="mediaURL(preview)" style="display:block;max-width:100%;max-height:75vh;margin:auto"><video v-else-if="preview" :src="mediaURL(preview)" controls autoplay style="display:block;max-width:100%;max-height:75vh;margin:auto"/><template #footer><el-button v-if="preview" tag="a" :href="`${mediaURL(preview)}?download=1`">下载原文件</el-button></template></el-dialog></section></template>
